import{_ as e,c as o,o as a,ag as n}from"./chunks/framework._xRlcm3f.js";const f=JSON.parse('{"title":"Confluence 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/confluence.md","filePath":"platforms/confluence.md","lastUpdated":1790228279000}'),l={name:"platforms/confluence.md"};function r(c,t,d,s,i,u){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="confluence-配置指南" tabindex="-1">Confluence 配置指南 <a class="header-anchor" href="#confluence-配置指南" aria-label="Permalink to &quot;Confluence 配置指南&quot;">​</a></h1><p>通过 <strong>Atlassian Confluence</strong> 发布文档。</p><p>Confluence 使用个人访问令牌（Personal Access Token, PAT）鉴权，按「空间」发布；可选择挂载到某个「父页面」下。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可访问的 Confluence 站点（如 <code>http://localhost:8090</code>）。</li><li>一个可用的 <strong>个人访问令牌（PAT）</strong>：登录 Confluence 后访问「个人访问令牌」页面（<code>/plugins/personalaccesstokens/usertokens.action</code>）创建并复制。PAT 只在创建时展示一次，请妥善保存。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>Confluence 站点首页地址，如 <code>http://localhost:8090</code></td></tr><tr><td>API 地址</td><td>Confluence API 地址，修改首页后通常自动同步</td></tr><tr><td>鉴权令牌</td><td>上一步生成的个人访问令牌（PAT）</td></tr><tr><td>父页面 ID</td><td>可选：将页面挂载到指定父页面下；不填则为顶层页面</td></tr><tr><td>空间</td><td>选择目标空间（Space），验证后会拉取账号可访问的空间列表</td></tr><tr><td>图床服务</td><td>默认用「当前平台」（Confluence 自带附件）上传图片；也可选 PicGo 等图床方案</td></tr></tbody></table><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>填写平台首页、鉴权令牌，点「验证」→ 拉取空间列表 → 选择目标空间并保存。</li><li>快速发布 → 选 Confluence → 发布。发布后可在「查看文章」打开页面。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证失败或提示「请求 Confluence API 异常」</strong>：确认平台首页/API 地址可达、PAT 有效；通常是令牌无效或地址不可达。</li><li><strong>平台端文章已手动删除后无法删除</strong>：平台端文章不存在时，正常删除会失败，可在删除失败后点击「强制删除」仅解除本地关联（不会重新触达平台）。</li><li><strong>文章发布到哪里</strong>：发布到所选「空间」下；未选父页面时为顶层页面，否则挂载到父页面下。</li><li><strong>图片怎么发布</strong>：默认用当前平台（Confluence 自带附件）上传，图片以附件形式挂载到页面下，无需额外图床。</li></ul>',11)])])}const p=e(l,[["render",r]]);export{f as __pageData,p as default};
